429 : function createEventHandler(
430 :   state: AideState,
431 : ): (input: { event: OpenCodeEvent }) => Promise<void> {
432 :   const recordUsage = createOpenCodeUsageRecorder();
433 :   return async ({ event }) => {
434 :     switch (event.type) {
435 :       case "session.created":
436 :         establishContext(state, extractSessionId(event), "startup");
437 :         await handleSessionCreated(state, event);
438 :         break;
439 :       case "session.compacted": {
440 :         const session = extractSessionId(event);
441 :         establishContext(state, session, "unknown");
442 :         state.pruningTrackers.complete(session);
443 :         if (state.binary)
444 :           updateContextWindow(
445 :             state.binary,
446 :             state.cwd,
447 :             { host: "opencode", sessionId: session, actorId: session },
448 :             "compact",
449 :           );
450 :         break;
451 :       }
452 :       case "session.idle":
453 :         await handleSessionIdle(state, event);
454 :         break;
455 :       case "session.deleted":
456 :         await handleSessionDeleted(state, event);
457 :         break;
458 :       case "message.part.updated":
459 :         if (state.binary)
460 :           recordUsage(state.binary, state.cwd, event.properties.part);
461 :         await handleMessagePartUpdated(state, event);
462 :         break;
463 :       default:
464 :         // Ignore other events
465 :         break;
466 :     }
467 :   };
468 : }
