## `handleMessagePartUpdated` [function]
**File:** `src/opencode/hooks.ts:735-813` | **Signature:** `async function handleMessagePartUpdated(
  state: AideState,
  event: OpenCodeEvent,
): Promise<void>`

```
735 : async function handleMessagePartUpdated(
736 :   state: AideState,
737 :   event: OpenCodeEvent,
738 : ): Promise<void> {
739 :   // Skill injection: only process user text parts
740 :   const part = event.properties.part as OpenCodePart | undefined;
741 :   if (!part) return;
742 : 
743 :   // Only match skills for text parts (user messages)
744 :   if (part.type !== "text") return;
745 :   const textContent = (part as { text?: string }).text;
746 :   if (!textContent) return;
747 : 
748 :   // Dedup: don't re-process the same part
749 :   const partId = part.id || "";
750 :   if (partId && state.processedMessageParts.has(partId)) return;
751 :   if (partId) state.processedMessageParts.add(partId);
752 : 
753 :   // Cap dedup set size — evict oldest half to avoid cliff-edge re-processing
754 :   if (state.processedMessageParts.size > 1000) {
755 :     const entries = Array.from(state.processedMessageParts);
756 :     const keepFrom = Math.floor(entries.length / 2);
757 :     state.processedMessageParts.clear();
758 :     for (let i = keepFrom; i < entries.length; i++) {
759 :       state.processedMessageParts.add(entries[i]);
760 :     }
761 :     debug(
762 :       SOURCE,
763 :       `Evicted ${keepFrom} entries from processedMessageParts dedup set`,
764 :     );
765 :   }
766 : 
767 :   const prompt = textContent;
768 : 
769 :   // Store latest user prompt so system transform can match skills even if
770 :   // this event fires after the transform (defensive against ordering).
771 :   state.lastUserPrompt = prompt;
772 : 
773 :   // Emit a user-prompt observe event so the convergence detector can find
774 :   // corrective markers near edit sequences. Gated behind AIDE_REFLECT,
775 :   // mirroring src/hooks/skill-injector.ts for cross-harness parity.
776 :   if (state.binary && reflectEnabled(state.cwd)) {
777 :     try {
778 :       recordObserveEvent(state.binary, state.cwd, {
779 :         kind: "hook",
780 :         name: "user_prompt",
781 :         category: "input",
782 :         tokens: Math.round(prompt.length / 3.0),
783 :         session: extractSessionId(event),
784 :         attrs: { text: previewContent(prompt, 2000) },
785 :       });
786 :     } catch {
787 :       // Non-fatal
788 :     }
789 :   }
790 : 
791 :   const skills = discoverSkills(state.cwd, state.pluginRoot ?? undefined);
792 :   const matched = matchSkills(prompt, skills, 3, "opencode");
793 : 
794 :   if (matched.length > 0) {
795 :     try {
796 :       const context = formatSkillsContext(matched);
797 :       await state.client.app.log({
798 :         body: {
799 :           service: "aide",
800 :           level: "info",
801 :           message: `Matched ${matched.length} skills: ${matched.map((s) => s.name).join(", ")}`,
802 :         },
803 :       });
804 :       // Store matched skills for injection in system transform
805 :       state.pendingSkillsContext = context;
806 :     } catch (err) {
807 :       debug(
808 :         SOURCE,
809 :         `Failed to log/inject matched skills (non-critical): ${err}`,
810 :       );
811 :     }
812 :   }
813 : }
```

